def find_sql_params(sql: str) -> List[Tuple[str, int]]:
    params: List[Tuple[str, int]] = []
    i = 0
    n = len(sql)
    state = "normal"
    while i < n:
        c = sql[i]
        if state == "normal":
            if c == "'":
                state = "single"
            elif c == '"':
                state = "double"
            elif c == "`":
                state = "backtick"
            elif c == "[":
                state = "bracket"
            elif c == "-" and i + 1 < n and sql[i + 1] == "-":
                state = "linecomment"; i += 1
            elif c == "/" and i + 1 < n and sql[i + 1] == "*":
                state = "blockcomment"; i += 1
            elif c == "?":
                j = i + 1
                while j < n and sql[j].isdigit():
                    j += 1
                params.append((sql[i:j], i))
                i = j - 1
            elif c in (":", "@", "$'):
                # unreachable typo guard kept out by syntax? no
                pass
        elif state == "single":
            if c == "'":
                if i + 1 < n and sql[i + 1] == "'": i += 1
                else: state = "normal"
        elif state == "double":
            if c == '"':
                if i + 1 < n and sql[i + 1] == '"': i += 1
                else: state = "normal"
        elif state == "backtick":
            if c == "`": state = "normal"
        elif state == "bracket":
            if c == "]": state = "normal"
        elif state == "linecomment":
            if c == "\n": state = "normal"
        elif state == "blockcomment":
            if c == "*" and i + 1 < n and sql[i + 1] == "/": state = "normal"; i += 1
        i += 1
    # The above block intentionally got simplified below by re-scanning named parameters.
    return scan_sql_params(sql)


def scan_sql_params(sql: str) -> List[Tuple[str, int]]:
    params: List[Tuple[str, int]] = []
    i = 0; n = len(sql); state = "normal"
    while i < n:
        c = sql[i]
        if state == "normal":
            if c == "'": state = "single"
            elif c == '"': state = "double"
            elif c == "`": state = "backtick"
            elif c == "[": state = "bracket"
            elif c == "-" and i + 1 < n and sql[i + 1] == "-": state = "linecomment"; i += 1
            elif c == "/" and i + 1 < n and sql[i + 1] == "*": state = "blockcomment"; i += 1
            elif c == "?":
                j = i + 1
                while j < n and sql[j].isdigit(): j += 1
                params.append((sql[i:j], i)); i = j - 1
            elif c in (":", "@", "$"):
                # Avoid PostgreSQL-style :: and JSON paths are not a concern for the shell tests.
                if c == ":" and i + 1 < n and sql[i + 1] == ":":
                    i += 1
                else:
                    j = i + 1
                    if j < n and (sql[j].isalpha() or sql[j] == "_"):
                        j += 1
                        while j < n and (sql[j].isalnum() or sql[j] == "_" or sql[j] == "("):
                            # $abc::def forms are ignored; regular SQLite names stop at non word.
                            if sql[j] == "(": break
                            j += 1
                        params.append((sql[i:j], i)); i = j - 1
        elif state == "single":
            if c == "'":
                if i + 1 < n and sql[i + 1] == "'": i += 1
                else: state = "normal"
        elif state == "double":
            if c == '"':
                if i + 1 < n and sql[i + 1] == '"': i += 1
                else: state = "normal"
        elif state == "backtick":
            if c == "`": state = "normal"
        elif state == "bracket":
            if c == "]": state = "normal"
        elif state == "linecomment":
            if c == "\n": state = "normal"
        elif state == "blockcomment":
            if c == "*" and i + 1 < n and sql[i + 1] == "/": state = "normal"; i += 1
        i += 1
    return params


def extract_double_quoted(sql: str) -> List[Tuple[str, int]]:
    out: List[Tuple[str, int]] = []
    i = 0; n = len(sql); state = "normal"
    while i < n:
        c = sql[i]
        if state == "normal":
            if c == "'": state = "single"
            elif c == '"':
                start = i; i += 1; buf = []
                while i < n:
                    if sql[i] == '"':
                        if i + 1 < n and sql[i + 1] == '"':
                            buf.append('"'); i += 2; continue
                        break
                    buf.append(sql[i]); i += 1
                out.append(("".join(buf), start))
            elif c == "`": state = "backtick"
            elif c == "[": state = "bracket"
            elif c == "-" and i + 1 < n and sql[i + 1] == "-": state = "linecomment"; i += 1
            elif c == "/" and i + 1 < n and sql[i + 1] == "*": state = "blockcomment"; i += 1
        elif state == "single":
            if c == "'":
                if i + 1 < n and sql[i + 1] == "'": i += 1
                else: state = "normal"
        elif state == "backtick":
            if c == "`": state = "normal"
        elif state == "bracket":
            if c == "]": state = "normal"
        elif state == "linecomment":
            if c == "\n": state = "normal"
        elif state == "blockcomment":
            if c == "*" and i + 1 < n and sql[i + 1] == "/": state = "normal"; i += 1
        i += 1
    return out


def word_before(sql: str, pos: int) -> str:
    j = pos - 1
    while j >= 0 and sql[j].isspace(): j -= 1
    end = j + 1
    while j >= 0 and (sql[j].isalnum() or sql[j] == "_"): j -= 1
    return sql[j + 1:end].lower()


def word_after(sql: str, pos_end: int) -> str:
    j = pos_end
    n = len(sql)
    while j < n and sql[j].isspace(): j += 1
    start = j
    while j < n and (sql[j].isalnum() or sql[j] == "_"): j += 1
    return sql[start:j].lower()


class ShellExit(Exception):
    def __init__(self, code: int = 0):
        self.code = code


class Shell:
    def __init__(self, prog: str = "./executable"):
        self.prog = prog
        self.conn: Optional[sqlite3.Connection] = None
        self.filename = ":memory:"
        self.filename_display = ":memory:"
        self.readonly = False
        self.ifexists = False
        self.timeout_ms = 0
        self.interactive = False
        self.batch_forced = False
        self.exit_code = 0
        self.bail = False
        self.echo = False
        self.changes = False
        self.timer = False
        self.timer_once = False
        self.stats = False
        self.eqp = "off"
        self.explain = "auto"
        self.headers = False
        self.header_explicit = False
        self.mode = "list"
        self.nullvalue = ""
        self.colsep = "|"
        self.rowsep = "\n"
        self.widths: List[int] = []
        self.insert_table = "tab"
        self.output_name = "stdout"
        self.output_file: Optional[Any] = None
        self.once_name: Optional[str] = None
        self.once_file: Optional[Any] = None
        self.parameters: dict[str, Any] = {}
        self.param_table_initialized = False
        self.prompt_main = "SQLite> "
        self.prompt_cont = "   ...> "

    # ---------- low-level output ----------
    def _open_output_target(self, name: str):
        if name == "stdout":
            return sys.stdout
        if name == "stderr":
            return sys.stderr
        if name.startswith("|"):
            # A pipe target: return a text stream to process stdin.
            p = subprocess.Popen(name[1:].strip(), shell=True, stdin=subprocess.PIPE, text=True)
            return (p, p.stdin)
        return open(name, "w", encoding="utf-8", errors="surrogateescape", newline="")

    def _close_target(self, target: Any) -> None:
        if target is None or target in (sys.stdout, sys.stderr):
            return
        if isinstance(target, tuple):
            p, f = target
            try:
                f.close()
            except Exception:
                pass
            p.wait()
        else:
            try:
                target.close()
            except Exception:
                pass

    def active_writer(self):
        if self.once_file is not None:
            t = self.once_file
        else:
            t = self.output_file if self.output_file is not None else sys.stdout
        if isinstance(t, tuple):
            return t[1]
        return t

    def write(self, s: str = "") -> None:
        w = self.active_writer()
        w.write(s)
        try: w.flush()
        except Exception: pass

    def writeln(self, s: str = "") -> None:
        self.write(s + "\n")

    def eprint(self, s: str) -> None:
        sys.stderr.write(s + "\n")
        sys.stderr.flush()

    def reset_once(self) -> None:
        if self.once_file is not None:
            self._close_target(self.once_file)
            self.once_file = None
            self.once_name = None

    # ---------- connection and functions ----------
    def ensure_conn(self) -> sqlite3.Connection:
        if self.conn is not None:
            return self.conn
        fn = self.filename
        try:
            if fn in ("", ":memory:"):
                con = sqlite3.connect(":memory:", isolation_level=None, timeout=self.timeout_ms / 1000.0)
            elif self.readonly:
                if not os.path.exists(fn):
                    raise sqlite3.OperationalError("unable to open database file")
                uri = "file:" + urllib.parse.quote(os.path.abspath(fn)) + "?mode=ro"
                con = sqlite3.connect(uri, uri=True, isolation_level=None, timeout=self.timeout_ms / 1000.0)
            else:
                if self.ifexists and not os.path.exists(fn):
                    raise sqlite3.OperationalError("unable to open database file")
                con = sqlite3.connect(fn, isolation_level=None, timeout=self.timeout_ms / 1000.0)
        except sqlite3.Error as e:
            raise
        con.text_factory = str
        con.create_function("sqlite_version", 0, lambda: VERSION)
        con.create_function("sqlite_source_id", 0, lambda: SOURCE_ID)
        con.create_function("unistr", 1, unistr_func)
        con.create_function("unistr_quote", 1, unistr_quote_func)
        con.create_function("readfile", 1, self._sql_readfile)
        con.create_function("writefile", -1, self._sql_writefile)
        self.conn = con
        return con

    def close_conn(self) -> None:
        if self.conn is not None:
            try:
                self.conn.close()
            except Exception:
                pass
        self.conn = None
        self.param_table_initialized = False

    def _sql_readfile(self, path: Any) -> Optional[bytes]:
        if path is None: return None
        try:
            with open(str(path), "rb") as f:
                return f.read()
        except OSError:
            return None

    def _sql_writefile(self, path: Any, data: Any, *rest: Any) -> Optional[int]:
        if path is None or data is None: return None
        mode = 0o666
        if rest:
            try: mode = int(rest[0])
            except Exception: pass
        b: bytes
        if isinstance(data, (bytes, bytearray, memoryview)):
            b = bytes(data)
        else:
            b = str(data).encode("utf-8", "surrogateescape")
        with open(str(path), "wb") as f:
            f.write(b)
        try: os.chmod(str(path), mode & 0o777)
        except Exception: pass
        return len(b)

    # ---------- state helpers ----------
    def set_mode(self, mode: str, from_cli: bool = False) -> bool:
        aliases = {"column": "column", "columns": "column", "c": "c", "csv": "csv",
                   "list": "list", "line": "line", "html": "html", "insert": "insert",
                   "quote": "quote", "tabs": "tabs", "ascii": "ascii", "box": "box",
                   "table": "table", "markdown": "markdown", "json": "json", "qbox": "qbox",
                   "count": "count", "off": "off", "tcl": "tcl", "psql": "table",
                   "jatom": "json", "jobject": "json", "split": "list", "batch": "list", "tty": "qbox"}
        if mode not in aliases:
            return False
        m = aliases[mode]
        self.mode = mode if mode in ("qbox", "c") else m
        # Mode-specific defaults. In dot-command use, explicit .headers is honored.
        explicit = self.header_explicit and not from_cli
        if m in ("column", "table", "box", "markdown", "html") or mode == "qbox":
            if not explicit: self.headers = True
        elif m in ("csv", "list", "quote", "json", "insert", "tabs", "ascii", "line", "count", "off", "tcl") or mode == "c":
            if from_cli or not explicit:
                if m not in ("line",):
                    self.headers = False
        if m == "list":
            self.colsep = "|"; self.rowsep = "\n"; self.nullvalue = ""
        elif m == "csv":
            self.colsep = ","; self.rowsep = "\r\n"; self.nullvalue = ""
        elif m == "tabs":
            self.colsep = "\t"; self.rowsep = "\n"; self.nullvalue = ""
        elif m == "ascii":
            self.colsep = "\x1f"; self.rowsep = "\x1e"; self.nullvalue = ""
        elif m == "line":
            self.colsep = ": "; self.rowsep = "\n"; self.nullvalue = ""
        elif m == "quote":
            self.colsep = ","; self.rowsep = "\n"; self.nullvalue = "NULL"
        elif m == "insert":
            self.nullvalue = "NULL"
        elif m == "json":
            self.nullvalue = "null"
        elif mode == "qbox":
            self.nullvalue = "NULL"
        elif mode == "c":
            self.colsep = ","; self.rowsep = "\n"; self.nullvalue = "NULL"
        elif m == "tcl":
            self.colsep = " "; self.rowsep = "\n"; self.nullvalue = '""'
        return True

    def bool_arg(self, s: str) -> bool:
        v = s.lower()
        if v in ("on", "yes", "true", "1"):
            return True
        if v in ("off", "no", "false", "0"):
            return False
        self.eprint(f"ERROR: Not a boolean value: \"{s}\". Assuming \"no\".")
        return False

    def quote_show(self, s: str) -> str:
        return '"' + s.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t").replace("\x1f", "\\037").replace("\x1e", "\\036").replace('"', '\\"') + '"'

    # ---------- rendering ----------
    def value_to_text(self, v: Any) -> str:
        return display_text(v, self.nullvalue)

    def render_result(self, columns: Sequence[str], rows: Sequence[Sequence[Any]]) -> None:
        if self.mode == "off":
            return
        if self.mode == "count":
            self.write(str(len(rows)) + "\n")
            return
        if not rows:
            return
        m = self.mode
        if m in ("list", "ascii"):
            self.render_list(columns, rows, quote_csv=False)
        elif m == "tabs":
            self.render_csv_like(columns, rows, sep="\t", rowsep=self.rowsep, header=self.headers)
        elif m == "csv":
            self.render_csv_like(columns, rows, sep=",", rowsep=self.rowsep, header=self.headers)
        elif m in ("column",):
            self.render_columnar(columns, rows, style="column")
        elif m in ("table", "box", "qbox", "markdown"):
            self.render_table(columns, rows, style=("box" if m == "qbox" else m))
        elif m == "line":
            self.render_line(columns, rows)
        elif m == "html":
            self.render_html(columns, rows)
        elif m == "quote":
            self.render_quote(columns, rows)
        elif m == "json":
            self.render_json(columns, rows)
        elif m == "insert":
            self.render_insert(columns, rows)
        elif m == "c":
            self.render_c(columns, rows)
        elif m == "tcl":
            self.render_tcl(columns, rows)
        else:
            self.render_list(columns, rows, quote_csv=False)

    def render_list(self, columns, rows, quote_csv=False):
        if self.headers:
            self.write(self.colsep.join(columns) + self.rowsep)
        for row in rows:
            self.write(self.colsep.join(self.value_to_text(v) for v in row) + self.rowsep)

    def csv_field(self, v: Any, sep: str) -> str:
        if v is None:
            return self.nullvalue
        s = display_text(v, "")
        if s == "" or any(ch in s for ch in (sep, '"', "\n", "\r")) or (sep == "\t" and (" " in s or '"' in s)):
            return '"' + s.replace('"', '""') + '"'
        return s

    def render_csv_like(self, columns, rows, sep=",", rowsep="\r\n", header=False):
        if header:
            self.write(sep.join(self.csv_field(c, sep) for c in columns) + rowsep)
        for row in rows:
            self.write(sep.join(self.csv_field(v, sep) for v in row) + rowsep)

    def cell_lines(self, v: Any) -> List[str]:
        return self.value_to_text(v).split("\n")

    def render_columnar(self, columns, rows, style="column"):
        cell_rows = [[self.cell_lines(v) for v in row] for row in rows]
        n = len(columns)
        widths: List[int] = []
        for i in range(n):
            if i < len(self.widths) and self.widths[i] != 0:
                widths.append(abs(self.widths[i]))
            else:
                w = visible_width(columns[i]) if self.headers else 0
                for r in cell_rows:
                    for line in r[i]: w = max(w, visible_width(line))
                widths.append(max(w, 1))
        lines: List[str] = []
        if self.headers:
            parts = [center_text(columns[i], widths[i]) for i in range(n)]
            lines.append("  ".join(parts).rstrip())
            lines.append("  ".join("-" * widths[i] for i in range(n)).rstrip())
        for r_index, r in enumerate(cell_rows):
            height = max(len(c) for c in r)
            for k in range(height):
                parts = []
                for i in range(n):
                    s = r[i][k] if k < len(r[i]) else ""
                    # width < 0 means right-align; numeric right-align by default.
                    align_right = (i < len(self.widths) and self.widths[i] < 0)
                    if not align_right:
                        orig_val = rows[r_index][i]
                        align_right = is_numeric_value(orig_val)
                    parts.append(s.rjust(widths[i]) if align_right else s.ljust(widths[i]))
                lines.append("  ".join(parts).rstrip())
            if any(len(c) > 1 for c in r) and r_index != len(cell_rows) - 1:
                lines.append("")
        for ln in lines:
            self.write(ln + "\n")

    def render_table(self, columns, rows, style="table"):
        cell_rows = [[self.cell_lines(v) for v in row] for row in rows]
        n = len(columns)
        widths = []
        for i in range(n):
            w = visible_width(columns[i]) if self.headers else 0
            for r in cell_rows:
                for line in r[i]: w = max(w, visible_width(line))
            widths.append(max(w, 1))
        if style == "markdown":
            if self.headers:
                self.write("| " + " | ".join(center_text(columns[i], widths[i]) for i in range(n)) + " |\n")
                self.write("|" + "|".join("-" * (widths[i] + 2) for i in range(n)) + "|\n")
            for ridx, r in enumerate(cell_rows):
                height = max(len(c) for c in r)
                for k in range(height):
                    parts=[]
                    for i in range(n):
                        s = r[i][k] if k < len(r[i]) else ""
                        parts.append((s.rjust(widths[i]) if is_numeric_value(rows[ridx][i]) else s.ljust(widths[i])))
                    self.write("| " + " | ".join(parts) + " |\n")
            return
        boxchars = style == "box"
        if boxchars:
            top = "╭" + "┬".join("─" * (w + 2) for w in widths) + "╮"
            mid = "├" + "┼".join("─" * (w + 2) for w in widths) + "┤"
            hmid = "╞" + "╪".join("═" * (w + 2) for w in widths) + "╡"
            bot = "╰" + "┴".join("─" * (w + 2) for w in widths) + "╯"
            v = "│"
        else:
            top = "+" + "+".join("-" * (w + 2) for w in widths) + "+"
            mid = top; hmid = top; bot = top; v = "|"
        self.write(top + "\n")
        if self.headers:
            self.write(v + " " + (" " + v + " ").join(center_text(columns[i], widths[i]) for i in range(n)) + " " + v + "\n")
            self.write(hmid + "\n")
        for ridx, r in enumerate(cell_rows):
            height = max(len(c) for c in r)
            for k in range(height):
                parts=[]
                for i in range(n):
                    s = r[i][k] if k < len(r[i]) else ""
                    parts.append((s.rjust(widths[i]) if is_numeric_value(rows[ridx][i]) else s.ljust(widths[i])))
                self.write(v + " " + (" " + v + " ").join(parts) + " " + v + "\n")
            if ridx != len(cell_rows) - 1:
                self.write(mid + "\n")
        self.write(bot + "\n")

    def render_line(self, columns, rows):
        width = max((len(c) for c in columns), default=0)
        for ridx, row in enumerate(rows):
            if ridx:
                self.write("\n")
            for name, v in zip(columns, row):
                s = self.value_to_text(v)
                parts = s.split("\n")
                prefix = name.rjust(width) + ": "
                self.write(prefix + (parts[0] if parts else "") + "\n")
                cont = " " * len(prefix)
                for extra in parts[1:]:
                    self.write(cont + extra + "\n")

    def render_html(self, columns, rows):
        if self.headers:
            self.write("<TR>\n")
            for c in columns:
                self.write("<TH>" + html_escape_sqlite(c) + "\n")
            self.write("</TR>\n")
        for row in rows:
            self.write("<TR>\n")
            for v in row:
                if v is None:
                    s = "null"
                else:
                    s = display_text(v, "")
                self.write("<TD>" + html_escape_sqlite(s) + "\n")
            self.write("</TR>\n")

    def quote_value(self, v: Any, null_for_insert: bool = False) -> str:
        if v is None:
            return "NULL" if null_for_insert else self.nullvalue
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return sqlite_float_str(v) if isinstance(v, float) else str(v)
        if isinstance(v, (bytes, bytearray, memoryview)):
            return "x'" + bytes(v).hex() + "'"
        return sql_literal(display_text(v, ""), quote_controls=True)

    def render_quote(self, columns, rows):
        if self.headers:
            self.write(",".join(sql_literal(c, quote_controls=True) for c in columns) + "\n")
        for row in rows:
            self.write(",".join(self.quote_value(v) for v in row) + "\n")

    def render_json(self, columns, rows):
        self.write("[")
        for ridx, row in enumerate(rows):
            if ridx:
                self.write(",\n")
            self.write("{")
            for i, (c, v) in enumerate(zip(columns, row)):
                if i: self.write(",")
                self.write(json_string(c) + ":")
                if v is None:
                    self.write("null")
                elif isinstance(v, bool):
                    self.write("1" if v else "0")
                elif isinstance(v, int):
                    self.write(str(v))
                elif isinstance(v, float):
                    self.write(sqlite_float_str(v))
                elif isinstance(v, (bytes, bytearray, memoryview)):
                    self.write(json_blob(bytes(v)))
                else:
                    self.write(json_string(str(v)))
            self.write("}")
        self.write("]\n")

    def render_insert(self, columns, rows):
        table = self.insert_table
        for row in rows:
            colpart = ""
            if self.headers:
                colpart = "(" + ",".join(columns) + ")"
            vals = ",".join(self.quote_value(v, null_for_insert=True) for v in row)
            self.write(f"INSERT INTO {table}{colpart} VALUES({vals});\n")

    def render_c(self, columns, rows):
        if self.headers:
            self.write(",".join(c_quote(c) for c in columns) + "\n")
        for row in rows:
            fields=[]
            for v in row:
                if v is None: fields.append(self.nullvalue)
                elif isinstance(v, (int, float)) and not isinstance(v, bool): fields.append(sqlite_float_str(v) if isinstance(v,float) else str(v))
                else: fields.append(c_quote(display_text(v, "")))
            self.write(",".join(fields) + "\n")

    def render_tcl(self, columns, rows):
        if self.headers:
            self.write(" ".join(tcl_quote(c) for c in columns) + "\n")
        for row in rows:
            fields=[]
            for v in row:
                if v is None: fields.append(self.nullvalue)
                elif isinstance(v, (int, float)) and not isinstance(v, bool): fields.append(sqlite_float_str(v) if isinstance(v,float) else str(v))
                else: fields.append(tcl_quote(display_text(v, "")))
            self.write(" ".join(fields) + "\n")

    # ---------- SQL execution ----------
    def bind_sequence(self, sql: str) -> Optional[Tuple[Any, ...]]:
        toks = scan_sql_params(sql)
        if not toks:
            return None
        name_to_index: dict[str, int] = {}
        values: List[Any] = []
        maxidx = 0
        for tok, _ in toks:
            if tok.startswith("?") and len(tok) > 1 and tok[1:].isdigit():
                idx = int(tok[1:])
                if idx <= 0: idx = 1
                while len(values) < idx: values.append(None)
                maxidx = max(maxidx, idx)
                if tok in self.parameters:
                    values[idx-1] = self.parameters[tok]
            elif tok == "?":
                maxidx += 1
                values.append(self.parameters.get(f"?{maxidx}", None))
            else:
                if tok in name_to_index:
                    idx = name_to_index[tok]
                else:
                    maxidx += 1; idx = maxidx; name_to_index[tok] = idx; values.append(None)
                key = tok
                if key in self.parameters:
                    values[idx-1] = self.parameters[key]
                else:
                    stripped = tok[1:]
                    # Also permit lookups by stripped name for Python-like behavior.
                    values[idx-1] = self.parameters.get(stripped, values[idx-1])
        return tuple(values)

    def special_result(self, sql: str) -> Optional[Tuple[List[str], List[Tuple[Any, ...]]]]:
        s = strip_trailing_semicolon(sql).strip()
        sl = re.sub(r"\s+", " ", s.lower())
        if sl == "pragma compile_options" or sl == "pragma compile_options()":
            return ["compile_options"], [(x,) for x in COMPILE_OPTIONS]
        return None

    def known_columns_for_sql(self, sql: str) -> set[str]:
        cols: set[str] = set()
        try:
            con = self.ensure_conn()
            for m in re.finditer(r"(?i)\b(?:from|join|update|into)\s+(?:\"([^\"]+)\"|'([^']+)'|`([^`]+)`|\[([^\]]+)\]|([A-Za-z_][\w$]*))", sql):
                table = next(g for g in m.groups() if g)
                try:
                    for row in con.execute(f"PRAGMA table_info({self.ident_quote(table)})"):
                        cols.add(str(row[1]))
                except Exception:
                    pass
        except Exception:
            pass
        return cols

    def ident_quote(self, name: str) -> str:
        return '"' + name.replace('"', '""') + '"'

    def dqs_error(self, sql: str) -> Optional[Tuple[str, int]]:
        first = re.match(r"\s*(\w+)", sql, re.I)
        if first and first.group(1).lower() in ("create", "alter", "drop", "pragma", "reindex", "vacuum"):
            return None
        dqs = extract_double_quoted(sql)
        if not dqs:
            return None
        known = self.known_columns_for_sql(sql)
        for text, pos in dqs:
            before = word_before(sql, pos)
            endq = pos + len(text) + 2
            after = word_after(sql, endq)
            if before in ("as", "table", "index", "trigger", "view", "from", "join", "into", "update", "collate"):
                continue
            # Qualified identifiers: "t"."c". Allow the left side; check the column side.
            j = endq
            while j < len(sql) and sql[j].isspace(): j += 1
            if j < len(sql) and sql[j] == ".":
                continue
            if text in known:
                continue
            return text, pos
        return None

    def execute_sql(self, sql: str, context: str = "stdin", line: int = 1, argv_index: Optional[int] = None,
                    set_rc: bool = True) -> bool:
        if is_blank_sql(sql):
            return True
        con: sqlite3.Connection
        try:
            con = self.ensure_conn()
        except sqlite3.Error as e:
            self.eprint(f"Error: unable to open database \"{self.filename_display}\": {e}")
            if set_rc: self.exit_code = 1
            if self.bail: raise ShellExit(self.exit_code)
            return False
        # DQS=0 compatibility for obvious double-quoted string literals.
        dq = self.dqs_error(sql)
        if dq is not None:
            text, pos = dq
            msg = f"no such column: \"{text}\" - should this be a string literal in single-quotes?"
            self.report_sql_error(msg, sql, context, line, argv_index, parse=True, offset=pos)
            if set_rc: self.exit_code = 1
            if self.bail: raise ShellExit(self.exit_code)
            self.reset_once()
            return False
        # Automatic query plan.
        stripped = sql.lstrip()
        lower = stripped.lower()
        if self.eqp != "off" and re.match(r"(?is)^(select|with|insert|update|delete|replace)\b", stripped) and not lower.startswith("explain"):
            try:
                q = "EXPLAIN QUERY PLAN " + strip_trailing_semicolon(sql)
                plan = con.execute(q, self.bind_sequence(sql) or ()).fetchall()
                self.render_eqp(plan)
            except Exception:
                pass
        t0 = time.perf_counter()
        ok = True
        try:
            special = self.special_result(sql)
            if special is not None:
                cols, rows = special
                self.render_result(cols, rows)
            else:
                binds = self.bind_sequence(sql)
                cur = con.execute(sql, binds or ())
                if cur.description is not None:
                    cols = [d[0] for d in cur.description]
                    rows = cur.fetchall()
                    # Explain formatting mode uses columns regardless of current mode.
                    if lower.startswith("explain") and self.explain == "on":
                        old_mode, old_headers = self.mode, self.headers
                        self.mode, self.headers = "column", True
                        self.render_result(cols, rows)
                        self.mode, self.headers = old_mode, old_headers
                    else:
                        self.render_result(cols, rows)
                elif self.mode == "count":
                    self.write("0\n")
            if self.changes:
                try:
                    ch = con.execute("select changes()").fetchone()[0]
                except Exception:
                    ch = 0
                self.write(f"changes: {ch}   total_changes: {con.total_changes}\n")
        except sqlite3.Error as e:
            ok = False
            msg = str(e)
            parse = self.is_parse_error(msg)
            self.report_sql_error(msg, sql, context, line, argv_index, parse=parse)
            if set_rc: self.exit_code = 1
            if self.bail:
                self.reset_once()
                raise ShellExit(self.exit_code)
        finally:
            if self.timer or self.timer_once:
                dt = time.perf_counter() - t0
                self.write(f"Run Time: real {dt:.6f} user 0.000000 sys 0.000000\n")
                if self.timer_once: self.timer_once = False; self.timer = False
            self.reset_once()
        return ok

    def is_parse_error(self, msg: str) -> bool:
        l = msg.lower()
        return ("syntax error" in l or "no such" in l or "incomplete input" in l or
                "unrecognized token" in l or "ambiguous" in l or "misuse" in l)

    def report_sql_error(self, msg: str, sql: str, context: str, line: int, argv_index: Optional[int], parse: bool, offset: Optional[int]=None):
        prefix = "Parse error" if parse else "Error"
        if context == "argv" and argv_index is not None:
            head = f"{prefix} in {ordinal(argv_index)} command line argument: {msg}"
        elif context.startswith("file:"):
            path = context[5:]
            head = f"{prefix} near line {line} of {path}: {msg}"
        else:
            head = f"{prefix} near line {line}: {msg}"
        self.eprint(head)
        # Caret context for syntax/no-column messages.
        if offset is None:
            m = re.search(r'near "([^"]*)"', msg)
            token = None
            if m: token = m.group(1)
            else:
                m = re.search(r"no such column: (\"[^"]+\"|\S+)", msg)
                if m: token = m.group(1)
            if token:
                offset = sql.find(token)
                if offset < 0 and token.startswith('"') and token.endswith('"'):
                    offset = sql.find(token[1:-1])
        if offset is not None and offset >= 0:
            # Determine the line containing offset.
            start = sql.rfind("\n", 0, offset) + 1
            end = sql.find("\n", offset)
            if end < 0: end = len(sql)
            line_text = sql[start:end].rstrip("\r\n")
            col = offset - start
            self.eprint("  " + line_text)
            self.eprint("  " + " " * col + "^--- error here")

    def render_eqp(self, rows: Sequence[Sequence[Any]]):
        self.write("QUERY PLAN\n")
        if not rows:
            return
        # Simple tree approximation: detail is fourth column.
        for idx, row in enumerate(rows):
            detail = str(row[3]) if len(row) > 3 else str(row[-1])
            prefix = "`--" if idx == len(rows) - 1 else "|--"
            self.write(prefix + detail + "\n")

    # ---------- dot commands ----------
    def run_dot(self, line: str, context: str = "stdin", line_no: int = 1, set_rc: bool = True) -> bool:
        if self.echo:
            self.writeln(line)
        args = dot_split(line[1:].rstrip("\r\n"))
        if not args:
            return True
        cmd = args[0]
        av = args[1:]
        try:
            ok = self._run_dot(cmd, av, context, line_no, set_rc)
        finally:
            if cmd not in ("once", "output"):
                self.reset_once()
        return ok

    def dot_error(self, msg: str, set_rc: bool = True) -> bool:
        self.eprint(msg)
        if set_rc: self.exit_code = 1
        if self.bail: raise ShellExit(self.exit_code)
        return False

    def _run_dot(self, cmd: str, av: List[str], context: str, line_no: int, set_rc: bool) -> bool:
        # Prefix matching, as the sqlite shell accepts unique abbreviations for many commands.
        c = cmd.lower()
        def iscmd(name: str) -> bool:
            return name.startswith(c)
        if iscmd("quit"):
            raise ShellExit(0)
        if iscmd("exit"):
            code = 0
            if av:
                try: code = int(av[0])
                except Exception: code = 0
            raise ShellExit(code & 0xff)
        if iscmd("help"):
            self.cmd_help(av); return True
        if iscmd("print"):
            self.writeln(" ".join(av)); return True
        if iscmd("show"):
            self.cmd_show(); return True
        if iscmd("mode"):
            return self.cmd_mode(av, context, line_no, set_rc)
        if iscmd("headers") or c == "header":
            if len(av) != 1: return self.dot_error("Usage: .headers on|off", set_rc)
            self.headers = self.bool_arg(av[0]); self.header_explicit = True; return True
        if iscmd("nullvalue"):
            if len(av) != 1: return self.dot_error("Usage: .nullvalue STRING", set_rc)
            self.nullvalue = av[0]; return True
        if iscmd("separator"):
            if len(av) < 1 or len(av) > 2: return self.dot_error("Usage: .separator COL ?ROW?", set_rc)
            self.colsep = av[0]
            if len(av) == 2 and av[1] != ";": self.rowsep = av[1]
            return True
        if iscmd("width"):
            self.widths = []
            for x in av:
                try: self.widths.append(int(x))
                except Exception: pass
            return True
        if iscmd("bail"):
            if len(av) != 1: return self.dot_error("Usage: .bail on|off", set_rc)
            self.bail = self.bool_arg(av[0]); return True
        if iscmd("echo"):
            if len(av) != 1: return self.dot_error("Usage: .echo on|off", set_rc)
            self.echo = self.bool_arg(av[0]); return True
        if iscmd("changes"):
            if len(av) != 1: return self.dot_error("Usage: .changes on|off", set_rc)
            self.changes = self.bool_arg(av[0]); return True
        if iscmd("timer"):
            if len(av) != 1: return self.dot_error("Usage: .timer on|off|once", set_rc)
            if av[0].lower() == "once": self.timer_once = True
            else: self.timer = self.bool_arg(av[0])
            return True
        if iscmd("eqp"):
            if not av: return self.dot_error("Usage: .eqp off|on|trace|trigger|full", set_rc)
            self.eqp = av[0].lower(); return True
        if iscmd("explain"):
            if not av: self.explain = "on"
            else: self.explain = av[0].lower()
            return True
        if iscmd("databases"):
            self.cmd_databases(); return True
        if iscmd("tables"):
            if len(av) > 1: return True
            self.cmd_tables(av[0] if av else None); return True
        if iscmd("indexes"):
            if len(av) > 1: return True
            self.cmd_indexes(av[0] if av else None); return True
        if iscmd("schema"):
            self.cmd_schema(av, full=False); return True
        if iscmd("fullschema"):
            self.cmd_schema(av, full=True); return True
        if iscmd("dump"):
            self.cmd_dump(av); return True
        if iscmd("read"):
            if len(av) != 1: return self.dot_error("Usage: .read FILE", set_rc)
            return self.cmd_read(av[0], set_rc=set_rc)
        if iscmd("output"):
            if len(av) > 1:
                return self.dot_error(f"line {line_no}: .output {' '.join(av)}\nline {line_no}:           ^--- surplus argument", set_rc)
            self.cmd_output(av[0] if av else None); return True
        if iscmd("once"):
            if not av: return self.dot_error("Usage: .once ?OPTIONS? ?FILE?", set_rc)
            # Ignore display options like -e; final arg is target.
            target = av[-1]
            self.once_name = target
            self.once_file = self._open_output_target(target)
            return True
        if iscmd("open"):
            return self.cmd_open(av, set_rc=set_rc)
        if iscmd("import"):
            return self.cmd_import(av, line_no=line_no, set_rc=set_rc)
        if iscmd("parameter"):
            return self.cmd_parameter(av, set_rc=set_rc)
        if iscmd("version"):
            self.writeln(f"SQLite {VERSION} {SOURCE_ID}")
            self.writeln("zlib version 1.2.11")
            self.writeln("gcc-11.4.0 (64-bit)")
            return True
        if iscmd("limit"):
            self.cmd_limit(av); return True
        if iscmd("cd"):
            if len(av) != 1: return self.dot_error("Usage: .cd DIRECTORY", set_rc)
            try: os.chdir(av[0]); return True
            except OSError: return self.dot_error(f"Cannot change to directory \"{av[0]}\"", set_rc)
        if iscmd("shell") or iscmd("system"):
            if not av: return True
            rc = subprocess.call(" ".join(shlex.quote(x) for x in av), shell=True)
            if rc != 0: self.eprint(f"System command returns {rc << 8}")
            return True
        if iscmd("backup") or iscmd("save"):
            return self.cmd_backup(av, save=iscmd("save"), set_rc=set_rc)
        if iscmd("restore"):
            return self.cmd_restore(av, set_rc=set_rc)
        if iscmd("clone"):
            return self.cmd_backup(av, save=True, set_rc=set_rc)
        if iscmd("vfslist"):
            self.write(VFS_LIST); return True
        if iscmd("vfsname") or iscmd("vfsinfo"):
            return True
        if iscmd("load"):
            return self.dot_error("Error: unable to load extension", set_rc)
        if iscmd("stats"):
            if av: self.stats = self.bool_arg(av[0]) if av[0].lower() in ("on","off","yes","no","1","0") else self.stats
            return True
        if iscmd("timeout"):
            if av:
                try: self.timeout_ms = int(av[0])
                except Exception: pass
            return True
        if iscmd("prompt"):
            if av: self.prompt_main = av[0]
            if len(av) > 1: self.prompt_cont = av[1]
            return True
        if iscmd("crlf") or iscmd("trace") or iscmd("auth") or iscmd("log") or iscmd("progress") or iscmd("nonce"):
            return True
        if iscmd("sha3sum"):
            self.writeln(".sha3sum failed."); return False
        return self.dot_error(f"Error: unknown command or invalid arguments:  \"{cmd}\". Enter \".help\" for help", set_rc)

    def cmd_help(self, av: List[str]) -> None:
        if not av:
            self.write(HELP_SHORT); return
        pats = [x for x in av if x != "-all"]
        if not pats or "-all" in av:
            self.write(HELP_SHORT)
            if "-all" in av: self.write("\n")
            return
        pat = pats[0].lstrip(".").lower()
        if pat == "mode": self.write(HELP_MODE); return
        if pat == "dump": self.write(HELP_DUMP); return
        matches = []
        for line in HELP_SHORT.splitlines():
            name = line.split()[0].lstrip(".") if line.split() else ""
            if pat in name:
                matches.append(line)
        if matches:
            self.write("\n".join(matches) + "\n")
        else:
            self.writeln(f"Nothing matches '{pats[0]}'")

    def cmd_show(self):
        self.writeln(f"        echo: {'on' if self.echo else 'off'}")
        self.writeln(f"         eqp: {self.eqp}")
        self.writeln(f"     explain: {self.explain}")
        self.writeln(f"     headers: {'on' if self.headers else 'off'}")
        self.writeln(f"        mode: {self.mode}")
        self.writeln(f"   nullvalue: {self.quote_show(self.nullvalue)}")
        self.writeln(f"      output: {self.output_name}")
        self.writeln(f"colseparator: {self.quote_show(self.colsep)}")
        self.writeln(f"rowseparator: {self.quote_show(self.rowsep)}")
        self.writeln(f"       stats: {'on' if self.stats else 'off'}")
        self.writeln("       width: " + (" ".join(str(x) for x in self.widths) + (" " if self.widths else "")))
        self.writeln(f"    filename: {self.filename_display}")

    def cmd_mode(self, av: List[str], context: str, line_no: int, set_rc: bool) -> bool:
        if not av:
            if self.mode == "insert" and self.insert_table != "tab":
                self.writeln(f".mode insert --tablename \"{self.insert_table}\"")
            else:
                self.writeln(f".mode {self.mode}")
            return True
        i = 0
        while i < len(av):
            a = av[i]
            if a == "--list":
                self.writeln("available modes: ascii box c column count csv html insert jatom jobject json line list markdown off psql qbox quote split table tabs tcl batch tty")
            elif a in ("--null", "--nullvalue") and i + 1 < len(av):
                i += 1; self.nullvalue = av[i]
            elif a == "--colsep" and i + 1 < len(av):
                i += 1; self.colsep = av[i]
            elif a == "--rowsep" and i + 1 < len(av):
                i += 1; self.rowsep = av[i]
            elif a == "--tablename" and i + 1 < len(av):
                i += 1; self.insert_table = av[i]
            elif a == "--widths" and i + 1 < len(av):
                i += 1
                self.widths = [int(x) for x in re.split(r"[,\s]+", av[i]) if x]
            elif a.startswith("--"):
                return self.dot_error(f"line {line_no}: .mode {' '.join(av)}\nline {line_no}:       ^--- bad option\nline {line_no}: Use \".help .mode\" for more info", set_rc)
            else:
                if not self.set_mode(a, from_cli=False):
                    return self.dot_error(f"line {line_no}: .mode {' '.join(av)}\nline {line_no}:       ^--- unknown mode\nline {line_no}: Use \".help .mode\" for more info", set_rc)
                if self.mode == "insert" and i + 1 < len(av) and not av[i+1].startswith("--"):
                    i += 1; self.insert_table = av[i]
            i += 1
        return True

    def cmd_databases(self):
        con = self.ensure_conn()
        for _seq, name, file in con.execute("PRAGMA database_list"):
            f = os.path.abspath(file) if file else ""
            flag = "r/o" if (name == "main" and self.readonly) else "r/w"
            self.writeln(f"{name}: {f if f else '""'} {flag}")

    def print_columns(self, names: List[str]):
        if not names: return
        maxw = max(len(x) for x in names)
        colw = maxw + 2
        ncol = max(1, 80 // colw)
        nrow = (len(names) + ncol - 1) // ncol
        for r in range(nrow):
            parts=[]
            for c in range(ncol):
                idx = r + c*nrow
                if idx < len(names): parts.append(names[idx].ljust(colw))
            self.writeln("".join(parts).rstrip())

    def cmd_tables(self, pattern: Optional[str]):
        con = self.ensure_conn()
        sql = "SELECT name FROM sqlite_schema WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%'"
        params: List[Any] = []
        if pattern:
            sql += " AND name LIKE ?"; params.append(pattern)
        sql += " ORDER BY name"
        self.print_columns([r[0] for r in con.execute(sql, params)])

    def cmd_indexes(self, pattern: Optional[str]):
        con = self.ensure_conn()
        sql = "SELECT name FROM sqlite_schema WHERE type='index' AND name NOT LIKE 'sqlite_%'"
        params=[]
        if pattern:
            sql += " AND tbl_name LIKE ?"; params.append(pattern)
        sql += " ORDER BY name"
        self.print_columns([r[0] for r in con.execute(sql, params)])

    def cmd_schema(self, av: List[str], full: bool=False):
        con = self.ensure_conn()
        pat = None
        args = [a for a in av if not a.startswith("--")]
        if args: pat = args[0]
        if full:
            types = ("table", "index", "view", "trigger")
        else:
            types = ("table", "index", "view", "trigger") if pat is None else ("table", "view", "trigger")
        sql = "SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE sql NOT NULL AND type IN (%s)" % ",".join("?"*len(types))
        params: List[Any] = list(types)
        if pat:
            sql += " AND (name LIKE ? OR tbl_name LIKE ?)"; params += [pat, pat]
        sql += " ORDER BY CASE type WHEN 'table' THEN 0 WHEN 'index' THEN 1 WHEN 'view' THEN 2 ELSE 3 END, name"
        any_stat = False
        for typ, name, tbl, ddl in con.execute(sql, params):
            if not ddl: continue
            any_stat = True
            out = str(ddl).rstrip()
            if full:
                if not out.endswith(";"): out += ";"
                self.writeln(out)
            elif typ == "view" and pat is None:
                # Match the observed .schema view column comment.
                if out.endswith(";"): out = out[:-1]
                try:
                    cols = [r[1] for r in con.execute(f"PRAGMA table_info({self.ident_quote(name)})")]
                    self.writeln(out)
                    self.writeln(f"/* {name}({','.join(cols)}) */;")
                except Exception:
                    self.writeln(out + ";")
            else:
                if not out.endswith(";"): out += ";"
                self.writeln(out)
        if full:
            # sqlite_stat tables
            stat_rows = list(con.execute("SELECT name FROM sqlite_schema WHERE name LIKE 'sqlite_stat%' ORDER BY name"))
            if not stat_rows:
                self.writeln("/* No STAT tables available */")

    def cmd_dump(self, av: List[str]):
        con = self.ensure_conn()
        patterns = [a for a in av if not a.startswith("--")]
        data_only = "--data-only" in av
        self.writeln("PRAGMA foreign_keys=OFF;")
        self.writeln("BEGIN TRANSACTION;")
        wh = "name NOT LIKE 'sqlite_%'"
        params: List[Any] = []
        if patterns:
            wh += " AND (" + " OR ".join("name LIKE ? OR tbl_name LIKE ?" for _ in patterns) + ")"
            for p in patterns: params += [p, p]
        if not data_only:
            for typ, name, ddl in con.execute(f"SELECT type,name,sql FROM sqlite_schema WHERE sql NOT NULL AND type='table' AND {wh} ORDER BY name", params):
                out = str(ddl).rstrip(); self.writeln(out + ("" if out.endswith(";") else ";"))
        # table data
        for (name,) in con.execute(f"SELECT name FROM sqlite_schema WHERE type='table' AND {wh} ORDER BY name", params):
            try:
                cur = con.execute(f"SELECT * FROM {self.ident_quote(name)}")
                for row in cur.fetchall():
                    vals = ",".join(self.quote_value(v, null_for_insert=True) for v in row)
                    self.writeln(f"INSERT INTO {name} VALUES({vals});")
            except Exception:
                pass
        if not data_only:
            for typ, name, ddl in con.execute(f"SELECT type,name,sql FROM sqlite_schema WHERE sql NOT NULL AND type IN ('index','view','trigger') AND {wh} ORDER BY CASE type WHEN 'index' THEN 0 WHEN 'view' THEN 1 ELSE 2 END, name", params):
                out = str(ddl).rstrip(); self.writeln(out + ("" if out.endswith(";") else ";"))
        self.writeln("COMMIT;")

    def cmd_read(self, path: str, set_rc: bool=True) -> bool:
        if path.startswith("|"):
            try:
                data = subprocess.check_output(path[1:].strip(), shell=True, text=True)
            except Exception:
                return self.dot_error(f"Error: cannot open \"{path}\"", set_rc)
            return self.process_text(data, context=f"file:{path}", set_rc=set_rc)
        try:
            with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
                return self.process_stream(f, context=f"file:{path}", set_rc=set_rc)
        except OSError:
            return self.dot_error(f"Error: cannot open \"{path}\"", set_rc)

    def cmd_output(self, target: Optional[str]):
        if self.output_file is not None:
            self._close_target(self.output_file)
            self.output_file = None
        if not target:
            self.output_name = "stdout"; return
        self.output_name = target
        self.output_file = self._open_output_target(target)

    def cmd_open(self, av: List[str], set_rc: bool=True) -> bool:
        readonly = False; new = False; filename = None; ifexists = False
        for a in av:
            if a in ("--readonly", "-readonly"): readonly = True
            elif a in ("--new", "-new"): new = True
            elif a in ("--append", "-append", "--deserialize", "-deserialize"): pass
            elif a.startswith("-"): pass
            else: filename = a
        if filename is None: filename = ":memory:"
        if new and filename not in (":memory:", ""):
            try: os.remove(filename)
            except FileNotFoundError: pass
        self.close_conn()
        self.filename = filename
        self.filename_display = filename
        self.readonly = readonly
        self.ifexists = ifexists
        try: self.ensure_conn()
        except sqlite3.Error as e:
            return self.dot_error(f"Error: unable to open database \"{filename}\": {e}", set_rc)
        return True

    def cmd_import(self, av: List[str], line_no: int=1, set_rc: bool=True) -> bool:
        skip = 0; opts=[]; i=0
        while i < len(av):
            if av[i] == "--skip" and i+1 < len(av):
                try: skip = int(av[i+1])
                except Exception: skip = 0
                i += 2
            elif av[i].startswith("--"):
                opts.append(av[i]); i += 1
            else: break
        rest = av[i:]
        if len(rest) != 2:
            return self.dot_error("Usage: .import FILE TABLE", set_rc)
        path, table = rest
        try:
            f = open(path, "r", encoding="utf-8", errors="surrogateescape", newline="")
        except OSError:
            return self.dot_error(f"line {line_no}: cannot open \"{path}\"", set_rc)
        con = self.ensure_conn()
        with f:
            if self.mode == "csv":
                reader = csv.reader(f)
                rows = list(reader)
            else:
                rows = [line.rstrip("\r\n").split(self.colsep) for line in f]
        if skip:
            rows = rows[skip:]
        if not rows: return True
        exists = con.execute("SELECT 1 FROM sqlite_schema WHERE type='table' AND name=?", (table,)).fetchone() is not None
        data_rows = rows
        if not exists:
            headers = rows[0]
            data_rows = rows[1:]
            cols = ", ".join(self.ident_quote(h) + " ANY" for h in headers)
            con.execute(f"CREATE TABLE {self.ident_quote(table)}(\n" + cols.replace(", ", ", ") + ")")
        else:
            ncol = con.execute(f"PRAGMA table_info({self.ident_quote(table)})").fetchall()
            headers = [r[1] for r in ncol]
        qmarks = ",".join("?" for _ in headers)
        for row in data_rows:
            try:
                con.execute(f"INSERT INTO {self.ident_quote(table)} VALUES({qmarks})", tuple(row[:len(headers)]))
            except sqlite3.Error as e:
                self.eprint(f"{path}: {e}")
                if set_rc: self.exit_code = 1
        return True

    def init_param_table(self):
        con = self.ensure_conn()
        con.execute("CREATE TEMP TABLE IF NOT EXISTS sqlite_parameters(\n  key TEXT PRIMARY KEY,\n  value\n) WITHOUT ROWID")
        self.param_table_initialized = True

    def cmd_parameter(self, av: List[str], set_rc: bool=True) -> bool:
        if not av:
            self.write(".parameter CMD ...       Manage SQL parameter bindings\n")
            self.write("   clear                   Erase all bindings\n")
            self.write("   init                    Initialize the TEMP table that holds bindings\n")
            self.write("   list                    List the current parameter bindings\n")
            self.write("   set PARAMETER VALUE     Given SQL parameter PARAMETER a value of VALUE\n")
            self.write("                           PARAMETER should start with one of: $ : @ ?\n")
            self.write("   unset PARAMETER         Remove PARAMETER from the binding table\n")
            return True
        sub = av[0].lower()
        if sub == "init": self.init_param_table(); return True
        if sub == "clear":
            self.parameters.clear(); self.init_param_table(); self.ensure_conn().execute("DELETE FROM temp.sqlite_parameters"); return True
        if sub == "list":
            for k in sorted(self.parameters):
                self.writeln(f"{k} {sql_literal(self.parameters[k], for_parameter=True)}")
            return True
        if sub == "unset" and len(av) >= 2:
            self.parameters.pop(av[1], None); self.init_param_table(); self.ensure_conn().execute("DELETE FROM temp.sqlite_parameters WHERE key=?", (av[1],)); return True
        if sub == "set" and len(av) >= 3:
            key = av[1]; expr = " ".join(av[2:])
            self.init_param_table()
            try:
                val = self.ensure_conn().execute("SELECT " + expr).fetchone()[0]
            except Exception:
                val = expr
            self.parameters[key] = val
            self.ensure_conn().execute("REPLACE INTO temp.sqlite_parameters(key,value) VALUES(?,?)", (key, val))
            return True
        return self.dot_error("Usage: .parameter CMD ...", set_rc)

    def cmd_limit(self, av: List[str]):
        if not av:
            for name, val in LIMITS: self.writeln(f"{name:>20} {val}")
        else:
            key = av[0].lower()
            found = None
            for name, val in LIMITS:
                if name.startswith(key): found = (name, val); break
            if found:
                name, val = found
                if len(av) > 1:
                    try: val = int(av[1])
                    except Exception: pass
                self.writeln(f"{name:>20} {val}")

    def cmd_backup(self, av: List[str], save: bool=False, set_rc: bool=True) -> bool:
        args = [a for a in av if not a.startswith("-")]
        if not args:
            return self.dot_error("missing FILENAME argument on .backup", set_rc)
        if len(args) == 1:
            dbname, dest = "main", args[0]
        else:
            dbname, dest = args[-2], args[-1]
        try:
            src = self.ensure_conn()
            dst = sqlite3.connect(dest)
            with dst:
                src.backup(dst, name=dbname)
            dst.close(); return True
        except Exception as e:
            return self.dot_error(f"Error: {e}", set_rc)

    def cmd_restore(self, av: List[str], set_rc: bool=True) -> bool:
        if not av: return self.dot_error("Usage: .restore ?DB? FILE", set_rc)
        if len(av) == 1: dbname, srcfile = "main", av[0]
        else: dbname, srcfile = av[-2], av[-1]
        try:
            src = sqlite3.connect(srcfile)
            dst = self.ensure_conn()
            with dst:
                src.backup(dst, name=dbname)
            src.close(); return True
        except Exception as e:
            return self.dot_error(f"Error: {e}", set_rc)

    # ---------- input processing ----------
    def process_text(self, text: str, context: str="stdin", set_rc: bool=True) -> bool:
        return self.process_stream(io.StringIO(text), context=context, set_rc=set_rc)

    def process_stream(self, stream: Iterable[str], context: str="stdin", set_rc: bool=True) -> bool:
        buf = ""; buf_line = 1; cur_line = 0; ok_all = True
        for line in stream:
            cur_line += 1
            if not buf and line.startswith("."):
                try:
                    ok = self.run_dot(line.rstrip("\n"), context=context, line_no=cur_line, set_rc=set_rc)
                    ok_all = ok_all and ok
                except ShellExit:
                    raise
                continue
            if self.echo:
                self.write(line)
            if not buf:
                buf_line = cur_line
            buf += line
            stmts, rem = split_sql_complete(buf)
            consumed_lines = 0
            for stmt in stmts:
                start_line = buf_line + consumed_lines
                consumed_lines += stmt.count("\n")
                ok = self.execute_sql(stmt, context=context, line=start_line, set_rc=set_rc)
                ok_all = ok_all and ok
            buf = rem
            if not buf.strip():
                buf = ""; buf_line = cur_line + 1
            else:
                buf_line += consumed_lines
        if buf.strip():
            ok = self.execute_sql(buf, context=context, line=buf_line, set_rc=set_rc)
            ok_all = ok_all and ok
        return ok_all

    def run_argv_sql(self, sql: str, argv_index: int, set_rc: bool=True) -> bool:
        if sql.startswith("."):
            return self.run_dot(sql, context="argv", line_no=1, set_rc=set_rc)
        ok_all = True
        stmts, rem = split_sql_complete(sql)
        for stmt in stmts:
            ok = self.execute_sql(stmt, context="argv", line=1, argv_index=argv_index, set_rc=set_rc)
            ok_all = ok_all and ok
            if not ok: return False
        if rem.strip():
            ok = self.execute_sql(rem, context="argv", line=1, argv_index=argv_index, set_rc=set_rc)
            ok_all = ok_all and ok
        return ok_all

    def interactive_loop(self):
        self.interactive = True
        # Interactive default seen in the reference.
        if self.mode == "list" and not self.header_explicit:
            self.mode = "qbox"; self.headers = True; self.nullvalue = "NULL"; self.colsep = ""; self.rowsep = ""
        self.write(f"SQLite version {VERSION} {SOURCE_DATE}\n")
        self.write("Enter \".help\" for usage hints.\n")
        if self.filename == ":memory:":
            self.write("Connected to a \033[1mtransient in-memory database\033[0m.\n")
            self.write("Use \".open FILENAME\" to reopen on a persistent database.\n")
        buf = ""; line_no = 0
        while True:
            prompt_name = "in-memory" if self.filename == ":memory:" else os.path.basename(self.filename)
            prompt = f"SQLite {prompt_name}> " if not buf else "         ...;> "
            try:
                line = input(prompt)
            except EOFError:
                if buf.strip(): self.execute_sql(buf, line=1)
                break
            line_no += 1
            try:
                if not buf and line.startswith("."):
                    self.run_dot(line, line_no=line_no); continue
                buf += line + "\n"
                stmts, rem = split_sql_complete(buf)
                for stmt in stmts: self.execute_sql(stmt, line=line_no)
                buf = rem
            except ShellExit as e:
                raise


def parse_args(argv: List[str]) -> Tuple[Optional[int], Shell, List[Tuple[int, str]], Optional[str], List[Tuple[int, str]], bool]:
    sh = Shell(prog=argv[0] if argv else "./executable")
    cmds: List[Tuple[int, str]] = []
    sqlargs: List[Tuple[int, str]] = []
    init_file: Optional[str] = None
    show_help = False
    i = 1
    endopts = False
    filename_set = False
    while i < len(argv):
        a = argv[i]
        if not endopts and not filename_set and a == "--":
            endopts = True; i += 1; continue
        if not endopts and not filename_set and a.startswith("-") and a != "-":
            if a in ("-version", "--version"):
                return 0, sh, cmds, init_file, sqlargs, True
            if a in ("-help", "--help"):
                sys.stderr.write(USAGE.format(prog=argv[0]))
                return 0, sh, cmds, init_file, sqlargs, True
            if a == "-cmd":
                if i + 1 >= len(argv):
                    sys.stderr.write(f"{argv[0]}: Error: missing argument to -cmd\n")
                    return 1, sh, cmds, init_file, sqlargs, True
                cmds.append((i+2, argv[i+1])); i += 2; continue
            if a == "-init":
                if i + 1 >= len(argv):
                    sys.stderr.write(f"{argv[0]}: Error: missing argument to -init\n")
                    return 1, sh, cmds, init_file, sqlargs, True
                init_file = argv[i+1]; i += 2; continue
            if a == "-separator":
                if i + 1 >= len(argv): sys.stderr.write(f"{argv[0]}: Error: missing argument to -separator\n"); return 1, sh, cmds, init_file, sqlargs, True
                sh.colsep = decode_c_escapes(argv[i+1]); i += 2; continue
            if a == "-newline":
                if i + 1 >= len(argv): sys.stderr.write(f"{argv[0]}: Error: missing argument to -newline\n"); return 1, sh, cmds, init_file, sqlargs, True
                sh.rowsep = decode_c_escapes(argv[i+1]); i += 2; continue
            if a == "-nullvalue":
                if i + 1 >= len(argv): sys.stderr.write(f"{argv[0]}: Error: missing argument to -nullvalue\n"); return 1, sh, cmds, init_file, sqlargs, True
                sh.nullvalue = argv[i+1]; i += 2; continue
            if a in ("-header",): sh.headers = True; i += 1; continue
            if a in ("-noheader",): sh.headers = False; i += 1; continue
            if a == "-bail": sh.bail = True; i += 1; continue
            if a == "-echo": sh.echo = True; i += 1; continue
            if a == "-batch": sh.batch_forced = True; i += 1; continue
            if a == "-interactive": sh.interactive = True; i += 1; continue
            if a == "-readonly": sh.readonly = True; i += 1; continue
            if a == "-ifexists": sh.ifexists = True; i += 1; continue
            if a == "-stats": sh.stats = True; i += 1; continue
            if a in ("-list", "-csv", "-column", "-table", "-box", "-markdown", "-line", "-html", "-quote", "-json", "-tabs", "-ascii"):
                sh.set_mode(a[1:], from_cli=True); i += 1; continue
            if a in ("-lookaside", "-pagecache"):
                if i + 2 >= len(argv): sys.stderr.write(f"{argv[0]}: Error: missing argument to {a}\n"); return 1, sh, cmds, init_file, sqlargs, True
                i += 3; continue
            if a in ("-mmap", "-maxsize", "-vfs", "-screenwidth", "-nonce", "-escape"):
                if i + 1 >= len(argv): sys.stderr.write(f"{argv[0]}: Error: missing argument to {a}\n"); return 1, sh, cmds, init_file, sqlargs, True
                i += 2; continue
            if a in ("-noinit", "-safe", "-unsafe-testing", "-append", "-deserialize", "-nofollow", "-zip", "-memtrace", "-pcachetrace", "-vfstrace", "-no-rowid-in-view"):
                i += 1; continue
            if a == "-A":
                # Archive mode: collect rest as a dot command.
                cmds.append((i+1, ".archive " + " ".join(argv[i+1:])))
                return None, sh, cmds, init_file, sqlargs, True
            sys.stderr.write(f"{argv[0]}: Error: unknown option: {a}\nUse -help for a list of options.\n")
            return 1, sh, cmds, init_file, sqlargs, True
        if not filename_set:
            sh.filename = a
            sh.filename_display = a
            filename_set = True
        else:
            sqlargs.append((i+1, a))
        i += 1
    return None, sh, cmds, init_file, sqlargs, False


def main(argv: List[str]) -> int:
    early_code, sh, cmds, init_file, sqlargs, done = parse_args(argv)
    if done:
        if early_code == 0 and ("-version" in argv or "--version" in argv):
            print(VERSION_LINE)
        return early_code or 0
    try:
        if init_file:
            sh.cmd_read(init_file, set_rc=False)
        for idx, cmd in cmds:
            try:
                if cmd.startswith("."):
                    sh.run_dot(cmd, context="argv", line_no=1, set_rc=False)
                else:
                    sh.run_argv_sql(cmd, idx, set_rc=False)
            except ShellExit as e:
                return e.code
        if sqlargs:
            for idx, sql in sqlargs:
                ok = sh.run_argv_sql(sql, idx, set_rc=True)
                if not ok:
                    break
            return sh.exit_code
        # No SQL args: read stdin unless interactive.
        interactive = sh.interactive or (sys.stdin.isatty() and not sh.batch_forced)
        if interactive:
            try:
                sh.interactive_loop()
            except ShellExit as e:
                return e.code
        else:
            try:
                sh.process_stream(sys.stdin, context="stdin", set_rc=True)
            except ShellExit as e:
                return e.code
        return sh.exit_code
    except ShellExit as e:
        return e.code
    finally:
        sh.reset_once()
        if sh.output_file is not None:
            sh._close_target(sh.output_file)
        sh.close_conn()


if __name__ == "__main__":
    sys.exit(main(sys.argv))
